mapper.select:
SELECT id, email, purpose, code_hash, expires_at, used_at, attempts, created_at
FROM email_verification_code
WHERE email = #{email}
  AND purpose = #{purpose}
ORDER BY created_at DESC
LIMIT 1

mapper.insert:
INSERT INTO email_verification_code (
    email, purpose, code_hash, expires_at, attempts, created_at
) VALUES (
    #{email}, #{purpose}, #{codeHash}, #{expiresAt}, 0, NOW()
)

mapper.update:
UPDATE email_verification_code
SET attempts = attempts + 1
WHERE id = #{id}

UPDATE email_verification_code
SET used_at = #{usedAt}
WHERE id = #{id}
